sys_script_include.script:
var HSBCContactManagementUtils = Class.create();
HSBCContactManagementUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    doesCombinationExist: function() {

        var counterpartyCode = this.getParameter('sysparm_counterparty_code');
        var businessProcess = this.getParameter('sysparm_business_process');
        var emailType = this.getParameter('sysparm_email_type');
        var emailAddress = this.getParameter('sysparm_email_address');

        var grCustomerContact = new GlideRecord('customer_contact');
        grCustomerContact.addQuery('u_counterparty_code', counterpartyCode);
        grCustomerContact.addQuery('u_business_process', businessProcess);
        grCustomerContact.addQuery('u_email_type', emailType);
        grCustomerContact.addQuery('email', emailAddress);
        grCustomerContact.query();

        if (grCustomerContact.next()) {
            var results = {
                "exists": "true",
                "message": gs.getMessage('HSBCContactExists')
            };
            return JSON.stringify(results);
        } else {
            return null;
        }
    },

    canAddOrUpdateContact: function() {

        var groupProperty = gs.getProperty('hsbc_contact_add_update_contact');

        if (gs.getUser().isMemberOf(group) || gs.getUser().hasRole('mss_manager')) {
            return true;
        } else {
            return false;
        }

    },

    getExistingContactDetails: function() {

        var contactObj = {};

        //Gliderecord lookup
        var gr = new GlideRecord("customer_contact");
        gr.addQuery('sys_id', this.getParameter('sysparm_counterparty_code'));
        gr.query();

        if (gr.next()) {
            contactObj.counterparty_code = gr.getValue('u_counterparty_code');
            contactObj.counterparty_description = gr.getValue('u_counterparty_description');
            contactObj.entity = gr.getValue('u_entity');
            contactObj.business_process = gr.getValue('u_business_process');
            contactObj.email_type = gr.getValue('u_email_type');
            contactObj.email_address = gr.getValue('email');
            contactObj.active = gr.getValue('active');
            contactObj.contact_type = gr.getValue('u_contact_type');
            contactObj.contact_number = gr.getValue('phone');
            contactObj.email_automation = gr.getValue('u_email_automation');
            contactObj.external_or_internal = gr.getValue('u_external_or_internal');
            contactObj.high_priority_client = gr.getValue('u_high_priority_client');
        }

        return JSON.stringify(contactObj);
    },

	getEmails: function() {
        var query = this.getParameter('sysparm_value');
        var selectedContacts = new GlideRecord("customer_contact");
        selectedContacts.addEncodedQuery('sys_idIN'+query);
        selectedContacts.query();
        var returnedContactsList = [];
        //Retrieve the list of all records with sys id passed
		while (selectedContacts.next()) {
            returnedContactsList.push(selectedContacts.email.toString());
        }
        return returnedContactsList.join(',');
    },

    type: 'HSBCContactManagementUtils'
});
